import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    R, C, X, Y, D, L = map(int, data)
    MOD = 1000000007

    if D + L != X * Y:
        print(0)
        return

    def comb(n, k):
        if k < 0 or k > n:
            return 0
        k = min(k, n - k)
        num = 1
        for i in range(k):
            num = num * (n - i) % MOD
        den = 1
        for i in range(1, k + 1):
            den = den * i % MOD
        return num * pow(den, MOD - 2, MOD) % MOD

    ans = comb(X - 1, D - 1) * comb(Y - 1, L - 1) % MOD
    print(ans)

if __name__ == "__main__":
    solve()

